-- StudyMate foundation migration: inspect and test before deploying.
create extension if not exists pgcrypto;
create extension if not exists vector;
create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, preferred_name text, institution_id uuid, created_at timestamptz not null default now());
create table public.institutions (id uuid primary key default gen_random_uuid(), code text unique not null, name text not null, verified boolean not null default false);
alter table public.profiles add constraint profile_institution_fk foreign key (institution_id) references public.institutions(id);
create table public.departments (id uuid primary key default gen_random_uuid(), institution_id uuid not null references public.institutions(id), faculty text not null, name text not null, unique(institution_id,faculty,name));
create table public.courses (id uuid primary key default gen_random_uuid(), owner_id uuid not null references auth.users(id), department_id uuid references public.departments(id), code text not null, title text, semester text, level integer, units integer, created_at timestamptz default now());
create table public.topics (id uuid primary key default gen_random_uuid(), course_id uuid not null references public.courses(id) on delete cascade, title text not null, unique(course_id,title));
create table public.sources (id uuid primary key default gen_random_uuid(), owner_id uuid not null references auth.users(id), course_id uuid not null references public.courses(id) on delete cascade, topic_id uuid references public.topics(id), kind text not null check(kind in ('audio','pdf','docx','pptx','txt','image','manual')), object_path text, sha256 text, version integer not null default 1, processing_state text not null default 'pending', retention_policy text not null default 'delete_after_verified_notes', created_at timestamptz not null default now());
create table public.source_chunks (id uuid primary key default gen_random_uuid(), source_id uuid not null references public.sources(id) on delete cascade, ordinal integer not null, content text not null, page_number integer, start_ms bigint, end_ms bigint, embedding vector(1536), unique(source_id,ordinal));
create table public.notes (id uuid primary key default gen_random_uuid(), owner_id uuid not null references auth.users(id), course_id uuid not null references public.courses(id), topic_id uuid references public.topics(id), source_id uuid references public.sources(id), source_version integer, body text not null default '', version integer not null default 1, saved_at timestamptz not null default now());
create table public.jobs (id uuid primary key default gen_random_uuid(), owner_id uuid not null references auth.users(id), course_id uuid not null references public.courses(id), source_id uuid references public.sources(id), kind text not null, state text not null default 'queued', idempotency_key text not null, attempts integer not null default 0, last_error text, leased_until timestamptz, created_at timestamptz not null default now(), unique(owner_id,idempotency_key));
create table public.flashcards (id uuid primary key default gen_random_uuid(), owner_id uuid not null references auth.users(id), course_id uuid not null references public.courses(id), topic_id uuid references public.topics(id), source_id uuid references public.sources(id), question text not null, answer text not null, due_at timestamptz default now(), interval_days integer not null default 0);
create table public.assessments (id uuid primary key default gen_random_uuid(), owner_id uuid not null references auth.users(id), course_id uuid not null references public.courses(id), topic_id uuid references public.topics(id), score numeric, created_at timestamptz default now());
create table public.study_tasks (id uuid primary key default gen_random_uuid(), owner_id uuid not null references auth.users(id), course_id uuid not null references public.courses(id), description text not null, done boolean not null default false, due_at timestamptz);
create table public.groups (id uuid primary key default gen_random_uuid(), owner_id uuid not null references auth.users(id), course_id uuid references public.courses(id), name text not null);
create table public.group_members (group_id uuid not null references public.groups(id) on delete cascade, user_id uuid not null references auth.users(id), role text not null default 'member', primary key(group_id,user_id));
create table public.resource_grants (id uuid primary key default gen_random_uuid(), owner_id uuid not null references auth.users(id), source_id uuid not null references public.sources(id) on delete cascade, group_id uuid not null references public.groups(id) on delete cascade, unique(source_id,group_id));
create table public.subscriptions (id uuid primary key default gen_random_uuid(), owner_id uuid not null unique references auth.users(id), tier text not null default 'free', status text not null default 'inactive', provider_reference text, renews_at timestamptz);
create table public.payment_events (id uuid primary key default gen_random_uuid(), provider_event_id text not null unique, reference text, verified boolean not null default false, received_at timestamptz not null default now());
create table public.usage_events (id uuid primary key default gen_random_uuid(), owner_id uuid not null references auth.users(id), job_id uuid references public.jobs(id), metric text not null, amount numeric not null, created_at timestamptz default now());
create table public.audit_events (id uuid primary key default gen_random_uuid(), actor_id uuid references auth.users(id), action text not null, entity_type text, entity_id uuid, created_at timestamptz default now());
-- Client access is denied by default on all tables, then selectively allowed for owner-controlled rows.
do $$ declare t text; begin foreach t in array array['profiles','institutions','departments','courses','topics','sources','source_chunks','notes','jobs','flashcards','assessments','study_tasks','groups','group_members','resource_grants','subscriptions','payment_events','usage_events','audit_events'] loop execute format('alter table public.%I enable row level security',t); end loop; end $$;
create policy institution_read on public.institutions for select to authenticated using (true);
create policy department_read on public.departments for select to authenticated using (true);
create policy profile_owner on public.profiles for all to authenticated using(id=auth.uid()) with check(id=auth.uid());
create policy course_owner on public.courses for all to authenticated using(owner_id=auth.uid()) with check(owner_id=auth.uid());
create policy topic_owner on public.topics for all to authenticated using(exists(select 1 from public.courses c where c.id=course_id and c.owner_id=auth.uid())) with check(exists(select 1 from public.courses c where c.id=course_id and c.owner_id=auth.uid()));
create policy source_owner on public.sources for all to authenticated using(owner_id=auth.uid()) with check(owner_id=auth.uid() and exists(select 1 from public.courses c where c.id=course_id and c.owner_id=auth.uid()));
create policy chunks_read_owner on public.source_chunks for select to authenticated using(exists(select 1 from public.sources s where s.id=source_id and s.owner_id=auth.uid()));
create policy notes_owner on public.notes for all to authenticated using(owner_id=auth.uid()) with check(owner_id=auth.uid());
create policy flashcards_owner on public.flashcards for all to authenticated using(owner_id=auth.uid()) with check(owner_id=auth.uid());
create policy assessments_owner on public.assessments for all to authenticated using(owner_id=auth.uid()) with check(owner_id=auth.uid());
create policy tasks_owner on public.study_tasks for all to authenticated using(owner_id=auth.uid()) with check(owner_id=auth.uid());
create policy jobs_read_owner on public.jobs for select to authenticated using(owner_id=auth.uid());
create policy subscriptions_read_owner on public.subscriptions for select to authenticated using(owner_id=auth.uid());
create policy usage_read_owner on public.usage_events for select to authenticated using(owner_id=auth.uid());
create policy groups_owner on public.groups for all to authenticated using(owner_id=auth.uid()) with check(owner_id=auth.uid());
create policy members_read on public.group_members for select to authenticated using(user_id=auth.uid() or exists(select 1 from public.groups g where g.id=group_id and g.owner_id=auth.uid()));
create policy grants_read_owner on public.resource_grants for select to authenticated using(owner_id=auth.uid());
-- No client mutation policies on payments, jobs, usage, audit or embeddings. Privileged server writes require independent authorization.
insert into public.institutions(code,name,verified) values ('UNICAL','University of Calabar',true),('UNICROSS','University of Cross River State',true) on conflict(code) do nothing;
